import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`restaurant-launch-plan`,heroTitle:`Build your restaurant's attention plan in minutes`,heroSubtitle:`Perplexity Computer researches your local food scene, identifies press and creator targets, and builds a complete PR playbook — automatically.`,inputUrlCta:`Build my attention plan`,inputUrlPlaceholder:`yourrestaurant.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of this restaurant — extract the concept, cuisine, neighborhood, price point, brand voice, and any unique angles. Then research the local market: 1) Identify the top 10 local food trends and how this restaurant fits or stands out. 2) Find 15-20 local food creators, bloggers, and influencers who cover this cuisine or neighborhood — include their platforms, follower counts, and contact info where available. 3) Research 10 local food journalists and press outlets that cover restaurant openings, food culture, and dining guides. 4) Identify 5-8 direct competitors in the area — analyze their social presence, recent press coverage, and what's generating buzz for them. 5) Surface upcoming local food events, festivals, and community moments the restaurant could tie into. 6) Build a complete attention plan with: a prioritized outreach list with personalized pitch angles for each target, 10 content ideas tailored to the restaurant's brand and local audience, a 30-day PR calendar with weekly themes and tactics, and press release draft and media kit talking points. Format everything in a clean, actionable document organized by priority.`,heroOverlaySteps:[`Analyzing your restaurant's concept, cuisine, and brand positioning`,`Researching local food trends, creators, and press contacts`,`Mapping competitor buzz and identifying your unique angles`,`Outreach targets, content ideas, and PR calendar — ready to execute`],generatingSteps:[`Visiting {url} to extract your restaurant's concept, cuisine, and brand voice`,`Designing an agent to research local food creators, journalists, and competitor coverage`,`Configuring trend analysis, event tracking, and press angle identification for your market`,`Setting up your attention plan with outreach targets, content ideas, and a 30-day calendar`],featureSectionTitle:`From restaurant URL to PR playbook`,featureCardTitles:[`Connects to your restaurant stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Gmail, Canva, Slack — Computer organizes your outreach lists, drafts pitches, and tracks responses in the tools you already use.`,`Creator and press outreach lists with personalized angles. Competitor buzz analysis. 10 content ideas. A 30-day PR calendar. Press release draft and media kit talking points.`],capabilitySectionTitle:`Your PR team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a complete attention strategy.`,capabilityCards:[{title:`Local Scene Research`,description:`Computer can research food trends, neighborhood dining culture, and seasonal moments in your market — and map exactly where your restaurant fits.`},{title:`Creator & Press Targeting`,description:`Computer can find local food bloggers, influencers, and journalists who cover your cuisine and neighborhood — with personalized pitch angles for each.`},{title:`Competitor Buzz Analysis`,description:`Computer can track what's driving attention for nearby competitors — press hits, viral posts, event partnerships — and surface gaps you can own.`},{title:`Connect Your Tools`,description:`Computer can push outreach lists to Google Sheets, draft pitches in Gmail, organize campaigns in Notion, and share updates in Slack — all in one workflow.`},{title:`Remember & Learn`,description:`Computer can remember your brand voice, past outreach, and which angles landed — so every plan gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can track local food press, competitor mentions, and trending moments — and flag new PR opportunities as they appear.`}]});export{t as default};
